class Solution {
public:
    int numberOfPaths(int n, vector<vector<int>>& corridors) {
        vector<vector<int>> graph(n + 1);
        vector<unordered_set<int>> adjacent(n + 1);
        for (const auto& e : corridors) {
            graph[e[0]].push_back(e[1]);
            graph[e[1]].push_back(e[0]);
            adjacent[e[0]].insert(e[1]);
            adjacent[e[1]].insert(e[0]);
        }
        int triangles = 0;
        for (int a = 1; a <= n; ++a) {
            const auto& neighbors = graph[a];
            for (int i = 0; i < (int)neighbors.size(); ++i) {
                for (int j = i + 1; j < (int)neighbors.size(); ++j) {
                    if (adjacent[neighbors[i]].count(neighbors[j])) ++triangles;
                }
            }
        }
        return triangles / 3;
    }
};
